(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.KanjiDeckFavorites=api;})(typeof window!=='undefined'?window:globalThis,function(){
'use strict';const limit=10;
function valid(v,hasChar=()=>true){return v&&typeof v==='object'&&typeof v.name==='string'&&v.name.trim().length>0&&Array.from(v.name).length<=20&&!/[\x00-\x1f\x7f<>]/.test(v.name)&&Array.isArray(v.items)&&v.items.length===3&&new Set(v.items.map(i=>i?.instanceId)).size===3&&v.items.every(i=>i&&/^inst_[A-Za-z0-9_-]{1,90}$/.test(i.instanceId||'')&&hasChar(i.char)&&Array.isArray(i.equippedReadings)&&i.equippedReadings.length<=100&&new Set(i.equippedReadings).size===i.equippedReadings.length&&i.equippedReadings.every(r=>typeof r==='string'&&r.length>0&&r.length<=100&&!/[\x00-\x1f<>]/.test(r)))&&(v.formation===null||Array.isArray(v.formation)&&v.formation.length===3&&v.formation.every(p=>p&&['x','y','angle'].every(k=>Number.isFinite(p[k]))&&Math.abs(p.x)<=1&&p.y>=0&&p.y<=1&&Math.abs(p.angle)<=Math.PI));}
function validSave(s,hasChar){return(s.deckFavorites===undefined||Array.isArray(s.deckFavorites)&&s.deckFavorites.length<=limit&&new Set(s.deckFavorites.map(v=>v?.slot)).size===s.deckFavorites.length&&s.deckFavorites.every(v=>v&&Number.isInteger(v.slot)&&v.slot>=0&&v.slot<limit&&valid(v,hasChar)))&&(s.loadedDeckFormation===undefined||s.loadedDeckFormation===null||valid({name:'配置',items:[0,1,2].map(n=>({instanceId:'inst_'+n,char:'一',equippedReadings:[]})),formation:s.loadedDeckFormation}));}
function resolve(v,inventory,getUnlocked){const used=new Set(),items=[],missing=[],rubies=[];for(const saved of v.items){let item=inventory.find(i=>i.instanceId===saved.instanceId&&i.char===saved.char&&!used.has(i.instanceId));if(!item)item=inventory.filter(i=>i.char===saved.char&&!used.has(i.instanceId)).sort((a,b)=>b.level-a.level)[0];if(!item){missing.push(saved.char);continue;}used.add(item.instanceId);const unlocked=getUnlocked(item),equippedReadings=saved.equippedReadings.filter(r=>unlocked.includes(r));rubies.push(...saved.equippedReadings.filter(r=>!unlocked.includes(r)).map(r=>`${saved.char}：${r}`));items.push({item,equippedReadings});}return{items,missing,rubies};}
return{limit,valid,validSave,resolve};});
